svg.script:
var H = SVGAnim.Helpers;
var SCALE = 40;
var CHAO_Y_SVG = 420;

var v0_vertical = Math.sqrt(2 * 9.8 * 2);
var v0_horizontal = 1.0;

var bola = H.get('bola');
var sombra = H.get('sombra');
var svgRaiz = H.get('svgRaiz');

var engine = new SVGAnim.PhysicsEngine({
  gravity: 9.8,
  mass: 1.0,
  scale: SCALE,
  groundY: 0,
  restituicaoBase: 0.75,
  atritoQuiqueBase: 0.85,
  muRolamento: 0.5,
  fixedTimestep: 1 / 120,
  maxDelta: 0.1,
  alturaMaximaTela: 400
});

var camera = new SVGAnim.Camera({
  smoothness: 0.08,
  scale: SCALE,
  groundY: 0,
  screenCenterX: 400,
  screenGroundY: CHAO_Y_SVG,
  maxY: 400
});

var nuvens = new SVGAnim.ParallaxBackground({
  container: H.get('nuvensContainer'),
  modelId: '#nuvemModelo',
  numItems: 14,
  camera: camera,
  parallaxFactor: 0.6,
  scale: SCALE,
  screenWidth: 800,
  margin: 200
});

var perspectiva = new SVGAnim.PerspectiveLines({
  container: H.get('linhasPerspectiva'),
  camera: camera,
  scale: SCALE,
  screenWidth: 800,
  screenHeight: 500,
  groundY: CHAO_Y_SVG,
  vanishY: 200,
  step: 1.0,
  range: 10,
  strokeColor: 'rgba(0,80,0,0.25)',
  strokeWidth: '1.8'
});

var trajetoria = new SVGAnim.TrajectoryTracer({
  pathElement: H.get('trajetoriaPath'),
  camera: camera,
  scale: SCALE,
  groundY: CHAO_Y_SVG,
  active: true,
  recordEvery: 2,
  minDistance: 0.01
});

var regua = new SVGAnim.DynamicRuler({
  container: H.get('reguaDinamica'),
  camera: camera,
  scale: SCALE,
  groundY: CHAO_Y_SVG,
  screenWidth: 800,
  range: 5,
  tickHeight: 10,
  labelOffset: 15
});

var reguaVertical = new SVGAnim.VerticalRuler({
  container: H.get('reguaVertical'),
  groundY: CHAO_Y_SVG,
  maxHeight: 10,
  scale: SCALE,
  x: 10,
  width: 18,
  tickLengthLong: 7,
  tickLengthShort: 5,
  textOffsetX: 22,
  textAnchor: 'end'
});

var input = new SVGAnim.InputManager({
  svgElement: svgRaiz
});

var ui = new SVGAnim.UIManager();

function atualizarCena() {
  var state = engine.getState();

  camera.follow(state.x, state.y);

  bola.setAttribute('cy', camera.worldToScreenY(state.y));
  sombra.setAttribute('cy', CHAO_Y_SVG);

  var alturaMaxRef = (engine.gravity > 0) ? (v0_vertical * v0_vertical) / (2 * engine.gravity) : 1.0;
  var fatorAltura = Math.min(state.y / Math.max(alturaMaxRef, 0.1), 1.0);
  sombra.setAttribute('rx', Math.max(20 - 15 * fatorAltura, 3));
  sombra.setAttribute('opacity', Math.max(0.4 - 0.35 * fatorAltura, 0.05));

  regua.update();
  trajetoria.redraw(state.x);
  nuvens.update();
  perspectiva.update();
}

engine.onStep = function(state) {
  trajetoria.addPoint(state.x, state.y);
};

engine.onUpdate = function(state) {
  atualizarCena();
};

engine.onStop = function(state) {
  atualizarCena();
};

function animar(timestamp) {
  engine.step(timestamp);
  if (engine.isRunning()) {
    requestAnimationFrame(animar);
  }
}

function lancarBola() {
  if (engine.isRunning()) return;
  trajetoria.clear();
  camera.reset();
  var vx = input.isPressed('ArrowRight') ? v0_horizontal : 0;
  engine.launch(vx, v0_vertical);
  requestAnimationFrame(animar);
}

input.onKey('Space', lancarBola);

ui.bindInput('massaInput', 'massaDisplay', function(val) {
  engine.setMass(val);
}, { format: '1f' });

ui.bindInput('gravInput', 'gravDisplay', function(val) {
  engine.setGravity(val);
}, { format: '1f' });

ui.bindInput('v0yInput', 'v0yDisplay', function(val) {
  v0_vertical = val;
}, { format: '2f' });

ui.bindInput('v0xInput', 'v0xDisplay', function(val) {
  v0_horizontal = val;
}, { format: '1f' });

ui.bindCheckbox('mostrarTrajetoria', function(checked) {
  trajetoria.setActive(checked);
});

reguaVertical.render();
nuvens.init();
atualizarCena();
